meanings.gt_sql:
SELECT SUM(CASE WHEN home_team_api_id = 9987 THEN home_team_goal WHEN away_team_api_id = 9987 THEN away_team_goal ELSE 0 END) AS total_goals
FROM "Match"
WHERE season = '2008/2009' AND (home_team_api_id = 9987 OR away_team_api_id = 9987);

SELECT (SUM(CASE WHEN home_team_api_id = 9994 THEN home_team_goal ELSE 0 END) + SUM(CASE WHEN away_team_api_id = 9994 THEN away_team_goal ELSE 0 END)) AS total_goals
FROM "Match"
WHERE season = '2008/2009' AND (home_team_api_id = 9994 OR away_team_api_id = 9994);

